INSERT INTO tb_comic (title, img_url, sinopse, created_at, updated_at, published_at, language, size_in_bytes, image_format) VALUES ('X-Men #41 (2026)', 'https://cdn.marvel.com/u/prod/marvel/i/mg/c/a0/01a169577b02/detail.webp', 'The X-Men and the Fantastic Four are on a mission to save lives — but O*N*E has a mandate to enforce a quarantine zone and have their own mission to complete. Can both succeed?', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, TIMESTAMP WITH TIME ZONE '2023-01-15T10:00:00Z', 'English', 55000000, 'WEBP');
INSERT INTO tb_comic (title, img_url, sinopse, created_at, updated_at, published_at, language, size_in_bytes, image_format) VALUES ('Marvels – The Remastered Edition (TPB) (2018)', 'https://cdn.marvel.com/u/prod/marvel/i/mg/c/70/5be5fb932b83b/detail.webp', 'Within the Marvel Universe, heroes soar high in the skies, ready to battle the villains who threaten their world. Yet living in the shadow of these extraordinary icons are ordinary men and women who view the MARVELS with a mixture of fear, disbelief, envy and admiration. Among them is Phil Sheldon, a New York City photojournalist who has dedicated his career to covering the exploits of the Marvels and their effect on humankind. Written by Kurt Busiek and masterfully illustrated by Alex Ross, Marvels presents a richly painted historical overview of the entire Marvel Universe, spanning from the 1939 debut of the Human Torch to the fearsome coming of the world-devouring Galactus, and culminating in the shocking death of Gwen Stacy, Spider-Man’s first love. Collects Marvels #0-4.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, TIMESTAMP WITH TIME ZONE '2022-05-20T14:30:00Z', 'English', 335000000, 'WEBP');
INSERT INTO tb_comic (title, img_url, sinopse, created_at, updated_at, published_at, language, size_in_bytes, image_format) VALUES ('Batman – Arkham Asylum (2005)', 'https://www.guiadosquadrinhos.com/edicaoestrangeira/ShowImage.aspx?id=18762&path=ar161000_18762.jpg', 'The inmates of Arkham Asylum have taken over Gotham’s detention center for the criminally insane on April Fool’s Day, demanding Batman in exchange for their hostages. Accepting their demented challenge, Batman is forced to endure the personal hells of the Joker, Scarecrow, Poison Ivy, Two-Face and many other sworn enemies in order to save the innocents and retake the prison. During his run through this absurd gauntlet, the Dark Knight’s must face down both his most dangerous foes and his inner demons.This is the critically acclaimed Batman story that helped launch the U.S. careers of Grant Morrison and Dave McKean. The classic confrontation between the Dark Knight and his archnemeses, this story is well known for its psychological intensity and probing portraits of Batman and the Joker. ARKHAM ASYLUM includes groundbreaking art that influenced scores of artists by introducing a new school of storytelling and technique to comics. This special edition also includes Morrison’s complete original script, annotated by Morrison and editor Karen Berger, many of his original thumbnail breakdowns, step-by-step samples of how the story and art came together and much more.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, TIMESTAMP WITH TIME ZONE '2023-01-15T10:00:00Z', 'English', 55000000, 'JPEG');
INSERT INTO tb_comic (title, img_url, sinopse, created_at, updated_at, published_at, language, size_in_bytes, image_format) VALUES ('Teen Titans #3 (2026)', 'https://static.dc.com/dc/files/default_images/10a148da-8a2f-48d9-a811-2f15d0e54d4f/877e525e-60fd-4308-8cea-14c597309ffd/0.jpg', 'KYLE HIGGINS AND DANIELE DI NICUOLO REINVENT THE TEEN TITANS! Another kid has gone missing, and this time it’s one of the Teen Titans’ own! Eugene Choi was once a member of the mighty Shazam family, but now he’s powerless and helpless to prevent Ascend’s mission to stop the teen team. Could his disappearance reveal more about the organization’s true mission? Plus, Red Hood’s search comes to a devastating end.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, TIMESTAMP WITH TIME ZONE '2022-05-20T14:30:00Z', 'English', 335000000, 'JPEG');
INSERT INTO tb_comic (title, img_url, sinopse, created_at, updated_at, published_at, language, size_in_bytes, image_format) VALUES ('Savage Dragon #268 (2024)', 'https://imagecomics.com/files/releases/MAY230270.jpg', 'Malcolm Dragon is settling in to his new home on the West Coast – and his new job – containing and controlling the all-out mayhem in the region! It’s the start of a bold new direction as Malcolm Dragon assembles his team and faces a threat of unparalleled proportions! Strap in, for the ride of a lifetime!', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, TIMESTAMP WITH TIME ZONE '2023-01-15T10:00:00Z', 'English', 55000000, 'JPEG');
INSERT INTO tb_comic (title, img_url, sinopse, created_at, updated_at, published_at, language, size_in_bytes, image_format) VALUES ('Invincible Universe – Battle Beast #12 (2026)', 'https://imagecomics.com/files/releases/invincible-universe-battle-beast-12-CVRA.jpg', 'Seriously… did you think they’d only fight for two issues?', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, TIMESTAMP WITH TIME ZONE '2022-05-20T14:30:00Z', 'English', 335000000, 'JPEG');
INSERT INTO tb_comic (title, img_url, sinopse, created_at, updated_at, published_at, language, size_in_bytes, image_format) VALUES ('Dark Horse Classics – Godzilla King of the Monsters #1 – 6 (1998)', 'https://images.darkhorse.com/covers/400/d/dhcgkm1.jpg', 'A nightmare rises from the sea! A prehistoric monster is unleashed on the Atom Age! See a nation tremble in terror! See a mighty city laid to waste! See Godzilla’s first appearance in the modern world! Originally presented in 1987 in black-and-white, this comic has been newly colored and wrapped with a stunning painted cover by Hugo Award-winning artist Bob Eggleton.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, TIMESTAMP WITH TIME ZONE '2023-01-15T10:00:00Z', 'English', 55000000, 'JPEG');
INSERT INTO tb_comic (title, img_url, sinopse, created_at, updated_at, published_at, language, size_in_bytes, image_format) VALUES ('The Horror (2024)', 'https://images.darkhorse.com/covers/600/30/3006816.jpg', 'Travel with Colonel Kurtz and his family as they enter the “heart of darkness” on a humanitarian mission for Belgian King Leopold’s Congo Free State, opening a trading post in the uncharted interior of the Congo jungle to help promote free trade and abolish slavery in the region. With the help of a local tribe, they establish the post, but to survive in this lawless land, they must contend with murderous slave traders, corrupt officials, psychotic explorers, cannibalistic tribes, and the most dangerous threat of all: a primordial evil dwells deep within the jungle, whose origins and mythology date back to the womb to civilization, perverting minds and corrupting souls, while preying on the worst instincts of humanity. The locals speak of this insidious malevolence in fearful whispers, calling it “The Horror.”', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, TIMESTAMP WITH TIME ZONE '2022-05-20T14:30:00Z', 'English', 335000000, 'JPEG');
INSERT INTO tb_comic (title, img_url, sinopse, created_at, updated_at, published_at, language, size_in_bytes, image_format) VALUES ('The Story – Transformers – IDW Collection – Phase Two Vol. 1 – 12 (2014-2021)', 'https://i0.wp.com/getcomics.org/share/uploads/2017/12/Transformers-IDW-Collection-Phase-Two-Vol.-1-TPB-2014.jpg', 'The war for CYBERTRON is over but BUMBLEBEE and his fellow AUTOBOTS struggle to maintain control of a world without OPTIMUS PRIME. The provisional government is struggling and PROWL will defend it against the DECEPTICONS at seemingly all costs. Meanwhile, HOT ROD and a group of AUTOBOTS and DECEPTICONS embark on an epic quest to the farthest reaches of the Universe.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, TIMESTAMP WITH TIME ZONE '2023-01-15T10:00:00Z', 'English', 55000000, 'JPEG');
INSERT INTO tb_comic (title, img_url, sinopse, created_at, updated_at, published_at, language, size_in_bytes, image_format) VALUES ('The Story – Atomic Empire (2019)', 'https://i0.wp.com/getcomics.org/share/uploads/2019/09/Atomic-Empire-2019-IDW.jpg', 'An astonishing and captivating original graphic novel by Thierry Smolderen and Alexandre Clérisse. Inspired by a real psychological case, Atomic Empire is both a psychiatric enigma and a space opera. 1953: The world has entered the age of the Atom, but one man wonders what it means for civilization. His name is Paul—a sci-fi writer who, since childhood, has been in telepathic contact with a hero from the distant future. But when a well-known Pentagon consultant begins to take an interest in him, ”the man who communicates with the future” will commit an unforgivable sin and break an oath to his friend Zarth Arn, hero of the Galactic Empire. Smolderen and Clérisse deliver a beautiful and contemporary tale, immersed in the fluid and aerodynamic imagery of 1950s sci-fi.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, TIMESTAMP WITH TIME ZONE '2022-05-20T14:30:00Z', 'English', 335000000, 'JPEG');
INSERT INTO tb_comic (title, img_url, sinopse, created_at, updated_at, published_at, language, size_in_bytes, image_format) VALUES ('The Crow – Flesh and Blood #1 – 3 (1996)', 'https://i0.wp.com/getcomics.org/share/uploads/2026/11/The-Crow-Flesh-and-Blood-1-3-1996.jpg', 'Iris Shaw was a marshal for the Bureau of Land Management, before she was killed for threatening to expose violent criminals in her hometown. Then, the Crow gave her a chance to avenge her untimely demise.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, TIMESTAMP WITH TIME ZONE '2023-01-15T10:00:00Z', 'English', 55000000, 'JPEG');
INSERT INTO tb_comic (title, img_url, sinopse, created_at, updated_at, published_at, language, size_in_bytes, image_format) VALUES ('The Cimmerian – Xuthal of the Dusk #2 (2026)', 'https://i0.wp.com/getcomics.org/share/uploads/2026/08/The-Cimmerian-Xuthal-of-the-Dusk-2-2026.jpg', 'Conan the Cimmerian and his companion Natala sought respite within the mysterious city of Xuthal, but it soon became clear that there’s no respite to be had. Among abandoned feasts and lounges are mysterious, slithering shadows and a few incapacitated or panicked men. Finally, they encounter Thalis, a beautiful Stygian woman who seems content to tell them of Xuthal’s history and fate.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, TIMESTAMP WITH TIME ZONE '2022-05-20T14:30:00Z', 'English', 335000000, 'JPEG');
